class DiagnosisProbe:
    def run_full_diagnosis(self, train_loader):
        with preserve_module_modes_and_rng(self.view.model):
            self.view.model.eval()
            with torch.no_grad():
                result = run_existing_probes(train_loader)
                records = []
                for user, prefix, target in fixed_training_prefix_sample():
                    sequence = left_pad(prefix)
                    endpoint = largest_nonzero_index(sequence)
                    if endpoint is None:
                        continue
                    feature = self.view.log2feats(sequence)[endpoint]
                    eligible = real_training_items - set(training_history(user)) - {target}
                    negatives = deterministic_sample_without_replacement(eligible, maximum=999)
                    scores = score_in_chunks(self.view, feature, [target] + negatives)
                    for depth in (99, 499, 999):
                        if len(negatives) < depth:
                            record_unavailable(user, depth, reason='insufficient unique negatives')
                            continue
                        negative_scores = scores[1:depth + 1]
                        rank = rank_with_declared_tie_policy(scores[0], negative_scores)
                        records.append({user, depth, rank, diagnostic_hit_at_10: rank <= 10,
                                        margin_to_tenth_negative: scores[0] - tenth_largest(negative_scores),
                                        training_frequency_bin, prefix_length_bin})
                result.update(aggregate_with_paired_user_bootstrap(records))
                return {'metrics': result,
                        'metric_definitions': definitions_with_populations_ties_coverage_and_in_sample_warning()}

def diagnosis_interpreter_prompt(raw_diagnosis):
    return build_prompt(raw_diagnosis['metrics'], raw_diagnosis['metric_definitions'],
                        constraints='Exploratory training diagnostics; no inferred intent or validation gains; single NextItNet model per category.')
